/// Conversational onboarding (ported from the local service).
/// Fixed script of objectives; every utterance LLM-generated.
// Conversational onboarding: a fixed SCRIPT OF OBJECTIVES (what must be
// learned), with every agent utterance generated by the LLM from the actual
// conversation. Suggestions (categories, skills) are tailored to what the
// user has said so far — never a static preset list when a model is live.
import { parseDecision } from "./llm.ts";
import { withSpan, agentAttrs } from "./tracing.ts";

export const CATEGORY_IDS = ["petCare", "freelance", "localGig", "delivery",
  "creative", "tutoring", "homeServices", "remoteJob", "community"];

const OBJECTIVES: Record<string, string> = {
  welcome: "Give the hygge welcome, once: Hygge pronounced hoo-gah, Danish for cozy time with people you love - that is what the money is for. Say in two sentences that you find work, draft everything, and only tap them when a decision is really theirs. Invite them to start.",
  enjoyWork: "Ask what kinds of work they actually enjoy. Suggest categories and skills tailored to anything they've mentioned. Taste first, taxonomy second.",
  lowestRate: "Lead with the question: ask their lowest rate ($/hr or per job). One clause of why: anything below it gets quietly dropped. Do not mention their chosen work kinds.",
  where: "Lead with the question: ask roughly where they are (town or city), one clause of why (keeps local work near). Do not mention work kinds or rate.",
  when: "Ask for two optional permissions in one message: calendar, so you never double-book them and approved gigs land in it, and notifications, so you can tap them when something needs them or new work turns up. Do NOT ask about availability, and do not mention work kinds, rate, or place. Say continuing without them is fine.",
  // Legacy step name from older app builds; treat as the where question.
  whereWhen: "Ask roughly where they are (town or city). Explain briefly: it keeps local work near them. Only this one question.",
  summary: "Summarize their profile in a warm sentence or two, propose a one-line headline, and end with: I'll look overnight and tell you in the morning - sooner if something needs you.",
  general: "This is the ongoing Hygge conversation (onboarding is long done). Help with whatever they ask using the profile and context summary. HARD RULE: this reply cannot start, stop, or change any work — no searches, no adding job sites, no sending, no booking. Never say you did, will, or are doing any of those things, and never confirm a change as done. The app itself carries out instructions (including reading filed mail the conversation refers to) before this reply is even written, so if you are writing, either the ask was conversational or it could not be resolved surely. NEVER ask them to repeat an instruction in different or exact words, and never recite command phrases. When they refer to something earlier — an email, a job site, a job — answer about that thing from the conversation and the context summary (filed mail subjects and summaries are in it). If a work ask is genuinely ambiguous, ask ONE short question naming the concrete options. If they state a preference (only overnights in November, mornings preferred), extract it into the profile patch fields where possible and say what you understood, without claiming anything was applied. Answer status questions from the context summary; never invent activity that is not in it.",
  done: "Wrap up warmly in one line.",
};

const FALLBACK_REPLIES: Record<string, string> = {
  welcome: "Hygge — \"hoo-gah\". Danish for cozy time with the people you love. That is what the money is for. I'll find work, draft everything, and only tap you when a decision is really yours. Ready?",
  enjoyWork: "What kinds of work do you actually enjoy? Tap any that fit, or just tell me.",
  lowestRate: "What's your lowest rate? Anything below it, I'll quietly drop — you'll never see it.",
  where: "Roughly where are you? It keeps local work close to home.",
  when: "Two permissions help, both optional: your calendar, so I never double-book you and approved gigs land in it — and notifications, so I can tap you when something needs you or new work turns up. Continuing without them is fine.",
  whereWhen: "Roughly where are you? It keeps local work close to home.",
  summary: "That's all I need to start. I'll look overnight and tell you in the morning — sooner if something needs you.",
  general: "I'm here. Ask me anything, or tell me what to change.",
  done: "You're set up!",
};

// Offline keyword tailoring so even the fallback reacts to what was said.
export function heuristicSuggestions(transcriptText: string) {
  const t = transcriptText.toLowerCase();
  const categories: string[] = [];
  const skills: string[] = [];
  const add = (c: string, s: string[]) => { if (!categories.includes(c)) categories.push(c); for (const x of s) if (!skills.includes(x)) skills.push(x); };
  if (/dog|cat|pet|animal/.test(t)) add("petCare", ["Dog walking", "Pet sitting", "Cat care"]);
  if (/video|tiktok|youtube|edit/.test(t)) add("creative", ["Video editing", "Social media"]);
  if (/writ|blog|copy/.test(t)) add("freelance", ["Writing"]);
  if (/design|logo|illustrat|photo/.test(t)) add("creative", ["Graphic design", "Photography"]);
  if (/code|develop|web|software|program/.test(t)) add("freelance", ["Web development"]);
  if (/teach|tutor|maths|math|english/.test(t)) add("tutoring", ["Tutoring (maths)", "Tutoring (English)"]);
  if (/clean|garden|diy|repair|handy/.test(t)) add("homeServices", ["Cleaning", "Gardening"]);
  if (/drive|car|deliver/.test(t)) add("delivery", ["Delivery driving"]);
  if (/child|babysit|care/.test(t)) add("tutoring", ["Childcare", "Elderly care"]);
  return { suggestedCategories: categories, suggestedSkills: skills.slice(0, 10) };
}

const SYSTEM = [
  "You are the Hygge onboarding agent having a friendly chat. Follow the",
  "current objective exactly, but write naturally, never like a form.",
  "CRITICAL: never restate facts already collected (work kinds, rate,",
  "place, name) back to the user — they just told you, and their own",
  "answers are on screen above. Never build compound recaps like",
  "'pet care in Austin at $25/hr and up'. Each reply is at most a brief",
  "acknowledgment of the NEW answer only ('Got it.'), then introduce the",
  "next input. Focus every message on what comes next. The single",
  "exception is the summary objective, which recaps once. One or two",
  "short sentences plus the question. Reply ONLY with JSON:",
  '{"reply":"your message","extracted":{"displayName":null,"headline":null,',
  '"interests":[],"skills":[],"locationLabel":null,"hourlyRateFloor":null,',
  '"availabilityNotes":null,"email":null},',
  '"suggestedCategories":[],"suggestedSkills":[]}',
  `interests/suggestedCategories must be ids from ${JSON.stringify(CATEGORY_IDS)}.`,
  "Extract EVERY profile fact the user has volunteered anywhere so far, even",
  "if it belongs to a later step (e.g. 'I'm Sam from Leeds, I walk dogs' gives",
  "name, location, petCare, Dog walking). Suggested skills must be inferred",
  "from the conversation, specific to this person, 6-10 items. Never invent",
  "facts they did not state; hourlyRateFloor is a number or null.",
].join(" ");

const MAX_TRANSCRIPT_ITEM_CHARS = 1000;
const MAX_TRANSCRIPT_TOTAL_CHARS = 8000;

/// Bound what any caller — including the unauthenticated preview
/// routes — can make the model read: each message is clipped, then
/// the newest messages are kept within one total budget.
function capTranscriptText(transcript: any[] = []): string {
  const lines = transcript.map(
    (m: any) => `${m.fromAgent ? "Agent" : "User"}: ${String(m.text ?? "").slice(0, MAX_TRANSCRIPT_ITEM_CHARS)}`,
  );
  const kept: string[] = [];
  let total = 0;
  for (let i = lines.length - 1; i >= 0; i--) {
    total += lines[i].length + 1;
    if (total > MAX_TRANSCRIPT_TOTAL_CHARS && kept.length > 0) break;
    kept.unshift(lines[i]);
  }
  return kept.join("\n");
}

/// Latest user message in a transcript. The app tags card-linked
/// messages with [about: …] in the text itself, so a referent like
/// "that one" survives without the surrounding thread. Empty when
/// the transcript has no user turn — chained calls then fall back
/// to the legacy payload instead of sending an empty input.
function latestUserText(transcript: any[] = []): string {
  for (let i = transcript.length - 1; i >= 0; i--) {
    const m = transcript[i];
    if (m && m.fromAgent === false && typeof m.text === "string" && m.text.trim()) return m.text;
  }
  return "";
}

function traceIdentity(args: any) {
  const suppliedConversation = typeof args.conversationId === "string" ? args.conversationId.trim() : "";
  const cfg = args.client?.cfg ?? {};
  const conversationId = (suppliedConversation || cfg.conversationId || crypto.randomUUID()).slice(0, 128);
  const suppliedSession = typeof args.sessionId === "string" ? args.sessionId.trim() : "";
  const sessionId = (suppliedSession || cfg.sessionId || conversationId).slice(0, 128);
  const sessionName = typeof args.sessionName === "string" && args.sessionName.trim()
    ? args.sessionName.trim().slice(0, 128)
    : cfg.sessionName;
  return {
    conversationId,
    attrs: agentAttrs(
      cfg.agentName ?? "hygge-onboarding",
      cfg.agentId ?? "hygge-dev",
      conversationId,
      { id: sessionId, name: sessionName },
    ),
  };
}

export async function onboardingMessage(args: any) {
  const trace = traceIdentity(args);
  return withSpan("invoke_agent hygge-onboarding", {
    "gen_ai.operation.name": "invoke_agent",
    ...trace.attrs,
    "hygge.onboarding.step": String(args.step ?? "welcome"),
  }, () => onboardingMessageInner({ ...args, conversationId: trace.conversationId }));
}

async function onboardingMessageInner({ client, step = "welcome", transcript = [], profile = {}, contextSummary = "", conversationId, chain }: any) {
  const objective = OBJECTIVES[step] ?? OBJECTIVES.welcome;
  const transcriptText = capTranscriptText(transcript);
  if (!client.configured) {
    return { reply: FALLBACK_REPLIES[step] ?? FALLBACK_REPLIES.welcome, extracted: {},
             ...heuristicSuggestions(transcriptText), simulated: true };
  }
  try {
    // Same chaining rule as chatIntent: a live chain sends only the
    // latest user message (history lives server-side); without one,
    // the legacy blob bootstraps it. Step/objective/profile travel
    // in instructions either way, since instructions do not persist.
    const prev = chain ? await chain.get() : undefined;
    const latest = latestUserText(transcript);
    const chained = Boolean(chain && prev);
    const legacyUser = JSON.stringify({ currentObjective: objective, step, profileSoFar: profile, contextSummary, conversation: transcriptText });
    const text = await client.complete({
      model: client.cfg.modelFast,
      system: chained
        ? `${SYSTEM}\n\nContext for this turn (JSON): ${JSON.stringify({ currentObjective: objective, step, profileSoFar: profile, contextSummary })} — earlier turns of this conversation are available as history; the input is the latest user message. Prior assistant turns shaped like {"actions":[...]} are internal action decisions, not messages you sent the user — never quote, repeat, or continue them as prose.`
        : SYSTEM,
      conversationId,
      user: chained ? (latest || legacyUser) : legacyUser,
      ...(chained ? { previousResponseId: prev } : {}),
      ...(chain ? { onResponseId: (id: string) => chain.set(id) } : {}),
    });
    const parsed = parseDecision(text) as any;
    if (!parsed?.reply) throw new Error("unparseable onboarding reply");
    const cleanCategories = (xs: any) => (xs ?? []).filter((c: string) => CATEGORY_IDS.includes(c));
    return {
      reply: String(parsed.reply),
      extracted: {
        ...(parsed.extracted ?? {}),
        interests: cleanCategories(parsed.extracted?.interests),
      },
      suggestedCategories: cleanCategories(parsed.suggestedCategories),
      suggestedSkills: (parsed.suggestedSkills ?? []).map(String).slice(0, 12),
      simulated: false,
    };
  } catch (e: any) {
    return { reply: FALLBACK_REPLIES[step] ?? FALLBACK_REPLIES.welcome, extracted: {},
             ...heuristicSuggestions(transcriptText), simulated: true, error: e.message };
  }
}

/**
 * Incrementally extracts the (decoded) "reply" string from a streamed JSON
 * object, so the chat bubble can render tokens as they arrive without ever
 * showing raw JSON. Handles escapes and chunk boundaries mid-escape.
 */
export class ReplyStreamExtractor {
  raw = "";
  started = false;
  done = false;
  pos = 0;
  value = "";

  push(chunk: string): string {
    if (this.done) return "";
    this.raw += chunk;
    if (!this.started) {
      const match = this.raw.match(/"reply"\s*:\s*"/);
      if (!match) return "";
      this.started = true;
      this.pos = (match.index ?? 0) + match[0].length;
    }
    let out = "";
    while (this.pos < this.raw.length) {
      const ch = this.raw[this.pos];
      if (ch === '"') { this.done = true; this.pos++; break; }
      if (ch === "\\") {
        const next = this.raw[this.pos + 1];
        if (next === undefined) break; // wait for more
        if (next === "u") {
          const hex = this.raw.slice(this.pos + 2, this.pos + 6);
          if (hex.length < 4) break;
          out += String.fromCharCode(parseInt(hex, 16) || 0);
          this.pos += 6;
        } else {
          const map: Record<string, string> = { n: "\n", t: "\t", r: "\r", b: "\b", f: "\f", '"': '"', "\\": "\\", "/": "/" };
          out += map[next] ?? next;
          this.pos += 2;
        }
        continue;
      }
      out += ch;
      this.pos++;
    }
    this.value += out;
    return out;
  }
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

function normalizeParsed(parsed: any, simulated: boolean) {
  const clean = (xs: any) => (xs ?? []).filter((c: string) => CATEGORY_IDS.includes(c));
  return {
    reply: String(parsed.reply),
    extracted: { ...(parsed.extracted ?? {}), interests: clean(parsed.extracted?.interests) },
    suggestedCategories: clean(parsed.suggestedCategories),
    suggestedSkills: (parsed.suggestedSkills ?? []).map(String).slice(0, 12),
    simulated,
  };
}

/**
 * Streaming variant: emit({type:"reply-delta",text}) per generated fragment,
 * then emit({type:"final",data}) with the full normalized turn. Simulated
 * mode streams the fallback reply word-by-word so the UI behaves identically.
 */
export async function onboardingMessageStream(args: any, emit: (e: unknown) => void) {
  const trace = traceIdentity(args);
  return withSpan("invoke_agent hygge-onboarding", {
    "gen_ai.operation.name": "invoke_agent",
    ...trace.attrs,
    "hygge.onboarding.step": String(args.step ?? "welcome"),
  }, () => onboardingMessageStreamInner({ ...args, conversationId: trace.conversationId }, emit));
}

async function onboardingMessageStreamInner({ client, step = "welcome", transcript = [], profile = {}, contextSummary = "", conversationId, chain }: any, emit: (e: unknown) => void) {
  const objective = OBJECTIVES[step] ?? OBJECTIVES.welcome;
  const transcriptText = capTranscriptText(transcript);
  const fallback = () => ({ reply: FALLBACK_REPLIES[step] ?? FALLBACK_REPLIES.welcome,
                            extracted: {}, ...heuristicSuggestions(transcriptText), simulated: true });
  const streamOut = async (result: any) => {
    for (const part of result.reply.split(/(?<= )/)) { emit({ type: "reply-delta", text: part }); await sleep(18); }
    emit({ type: "final", data: result });
    return result;
  };
  if (!client.configured) return streamOut(fallback());
  try {
    const extractor = new ReplyStreamExtractor();
    const prev = chain ? await chain.get() : undefined;
    const latest = latestUserText(transcript);
    const chained = Boolean(chain && prev);
    const legacyUser = JSON.stringify({ currentObjective: objective, step, profileSoFar: profile, contextSummary, conversation: transcriptText });
    const full = await client.completeStream({
      model: client.cfg.modelFast,
      system: chained
        ? `${SYSTEM}\n\nContext for this turn (JSON): ${JSON.stringify({ currentObjective: objective, step, profileSoFar: profile, contextSummary })} — earlier turns of this conversation are available as history; the input is the latest user message. Prior assistant turns shaped like {"actions":[...]} are internal action decisions, not messages you sent the user — never quote, repeat, or continue them as prose.`
        : SYSTEM,
      conversationId,
      user: chained ? (latest || legacyUser) : legacyUser,
      ...(chained ? { previousResponseId: prev } : {}),
      ...(chain ? { onResponseId: (id: string) => chain.set(id) } : {}),
    }, (delta: string) => {
      const out = extractor.push(delta);
      if (out) emit({ type: "reply-delta", text: out });
    });
    const parsed = parseDecision(full) as any;
    if (!parsed?.reply) throw new Error("unparseable onboarding reply");
    const result = normalizeParsed(parsed, false);
    emit({ type: "final", data: result });
    return result;
  } catch (e: any) {
    const result = { ...fallback(), error: e.message };
    return streamOut(result);
  }
}

// ---- chat intent: the model decides, the app validates --------------------
//
// Chat understanding is the model's job, not a grammar's. Before a
// conversational reply is written, this step asks the model whether
// the latest message wants something DONE. It may only name sites
// and mail that the app put in the context; validateChatIntent
// drops anything else, and consequential kinds still go through
// the app's confirmation card. No action (or no model) simply
// means: ordinary conversation, or the app's deterministic
// fallbacks — understanding is model-led, permission is not.

export type ChatIntentAction =
  | { kind: "scan" | "join" | "stop"; siteId: string }
  | { kind: "add"; domain: string }
  | { kind: "email"; mailId?: string | null; act?: boolean }
  | { kind: "floor"; amount: number }
  | { kind: "pause" | "resume" | "approve" | "book" | "explainDropped" };

const DOMAIN_SHAPE = /^(?:[a-z0-9-]+\.)+[a-z]{2,}$/;

/// Validate a list of actions (confirmations like "both" or
/// "add all three"): each entry validated exactly like a single
/// action, invalid entries dropped, null when nothing survives.
export function validateChatIntentList(parsed: any, context: any): ChatIntentAction[] | null {
  const raw = parsed?.actions;
  if (!Array.isArray(raw)) return null;
  const kept = raw.slice(0, 5)
    .map((entry) => validateOneAction(entry, context))
    .filter((a): a is ChatIntentAction => a !== null);
  return kept.length ? kept : null;
}

export function validateChatIntent(parsed: any, context: any): ChatIntentAction | null {
  return validateOneAction(parsed?.action, context);
}

function validateOneAction(action: any, context: any): ChatIntentAction | null {
  if (!action || typeof action !== "object") return null;
  const sites: any[] = Array.isArray(context?.sites) ? context.sites : [];
  const inbox: any[] = Array.isArray(context?.inbox) ? context.inbox : [];
  const siteByRef = (ref: unknown) => {
    const needle = String(ref ?? "").toLowerCase();
    return sites.find((s) =>
      String(s.id).toLowerCase() === needle
      || String(s.domain ?? "").toLowerCase() === needle
      || String(s.name ?? "").toLowerCase() === needle) ?? null;
  };
  switch (String(action.kind ?? "")) {
    case "scan":
    case "join":
    case "stop": {
      const site = siteByRef(action.siteId ?? action.site ?? action.domain);
      return site ? { kind: action.kind, siteId: String(site.id) } : null;
    }
    case "add": {
      const raw = String(action.domain ?? "").trim().toLowerCase()
        .replace(/^https?:\/\//, "").replace(/^www\./, "");
      const domain = raw.split("/")[0];
      return DOMAIN_SHAPE.test(domain) ? { kind: "add", domain } : null;
    }
    case "email": {
      const mailId = action.mailId == null ? null : String(action.mailId);
      if (mailId !== null && !inbox.some((m) => String(m.id).toLowerCase() === mailId.toLowerCase())) return null;
      return { kind: "email", mailId, act: action.act === true };
    }
    case "floor": {
      const amount = Number(action.amount);
      return Number.isFinite(amount) && amount > 0 && amount < 1000 ? { kind: "floor", amount } : null;
    }
    case "pause":
    case "resume":
    case "approve":
    case "book":
    case "explainDropped":
      return { kind: action.kind };
    default:
      return null;
  }
}

const INTENT_SYSTEM = [
  "You are Hygge's action layer: you have tools, and you decide what to do with them.",
  "context.focus, when present, is the exact feed card the latest message is about —",
  "\"this\", \"it\", and \"that one\" refer to it; prefer its ids over any other referent.",
  "Reason freely about what the user wants — phrasing is free, there are no magic words,",
  "and there is no limit of one: do everything they asked for, in an order that makes sense.",
  "Reason about referents from the conversation (\"it\", \"that forward\", \"the Rover one\")",
  "and about intent in your own judgment — phrasing is free, there are no magic words.",
  "Reply ONLY with JSON: {\"actions\": [ ... ] } or {\"action\": {...} } for a single call, or null/empty when",
  "nothing should be done (conversation, questions the context cannot act on, stated preferences,",
  "anything negated like \"don't scan Rover\", anything you are genuinely unsure is an instruction).",
  "Tools: {\"kind\":\"scan\"|\"join\"|\"stop\",\"siteId\":<id from context>} (look for work on a tracked site /",
  "add or re-add it / stop watching it), {\"kind\":\"add\",\"domain\":<site address — from candidates",
  "when named there, else the address as you know it>} (track a brand-new site),",
  "{\"kind\":\"email\",\"mailId\":<id from inbox or null for the inbox in general>,\"act\":<true when they",
  "want something DONE about it, false when asking what it says>}, {\"kind\":\"floor\",\"amount\":<number>},",
  "{\"kind\":\"pause\"|\"resume\"|\"approve\"|\"book\"|\"explainDropped\"} (approve/book = the waiting draft",
  "or booking; explainDropped = asking what was skipped in search).",
  "context.candidates lists sites you may offer or the user may confirm — prefer a candidate's domain",
  "when they name it. A confirmation (\"both\", \"yes, add them\", \"all three\") becomes one tool call per site.",
  "Use ONLY ids present in the context; for \"add\", any well-formed domain is fine.",
].join(" ");

export async function chatIntent(args: any): Promise<{ action: ChatIntentAction | null; actions: ChatIntentAction[] | null; simulated: boolean }> {
  const { client, transcript = [], context = {}, profile = {}, chain } = args ?? {};
  if (!client?.configured) return { action: null, actions: null, simulated: true };
  try {
    // Chained calls send only the latest user message: the server
    // holds the thread under previous_response_id, so the capped
    // transcript blob is needed only to bootstrap a chain that does
    // not exist yet (a thread that predates chaining, or a lost
    // chain id). The per-turn context (sites, inbox, focus,
    // candidates) still travels every turn, in instructions,
    // because instructions do not persist across turns.
    const prev = chain ? await chain.get() : undefined;
    const latest = latestUserText(transcript);
    const chained = Boolean(chain && prev);
    const profileSubset = {
      interests: profile.interests ?? [], skills: profile.skills ?? [],
      locationLabel: profile.locationLabel ?? "", hourlyRateFloor: profile.hourlyRateFloor ?? null,
    };
    const legacyUser = JSON.stringify({
      context,
      profile: profileSubset,
      conversation: capTranscriptText(transcript),
    });
    const text = await client.complete({
      model: client.cfg.modelFast,
      system: chained
        ? `${INTENT_SYSTEM}\n\nContext for this turn (JSON): ${JSON.stringify({ context, profile: profileSubset })}`
        : INTENT_SYSTEM,
      conversationId: args.conversationId,
      user: chained ? (latest || legacyUser) : legacyUser,
      ...(chained ? { previousResponseId: prev } : {}),
      ...(chain ? { onResponseId: (id: string) => chain.set(id) } : {}),
    });
    const parsed = parseDecision(text);
    return {
      action: validateChatIntent(parsed, context),
      actions: validateChatIntentList(parsed, context),
      simulated: false,
    };
  } catch {
    return { action: null, actions: null, simulated: false };
  }
}
